from math import comb, gcd

def solve(p, alpha, A):
    MOD = 10**9 + 7
    if gcd(p, alpha) != 1 or alpha > p or alpha < 0:
        return 0
    if A < alpha:
        return 0
    if alpha == 0:
        return 1
    if alpha == 1:
        return A + 1
    if A > p:
        return 0
    count = 0
    for k in range(alpha, A + 1):
        n = k + 1
        while gcd(p, n) == 1 and n <= A:
            count += comb(A, k)
            n += A
        count %= MOD
    return count

