from collections import deque

def build_tree(n, k, labels):
    tree = [-1] * n
    parent = [i // 2 for i in range(1, n + 1)]
    while k > 0:
        labels = repeat(labels)
        k -= 1
    return tree, labels

def repeat(s):
    result = ""
    i = 0
    while i < len(s) - 1:
        result += s[i] * 2
        result += s[i]
        i += 1
    result += s[-1] * 2
    return result

def in_order(tree, labels, node=0):
    if tree[node] == 0:
        return ""
    result = labels[node]
    left = in_order(tree, labels, tree[node][0])
    right = in_order(tree, labels, tree[node][1])
    return left + result + right

def mutate(tree, labels, k, node=0):
    if tree[node] == 0:
        return labels[node], labels[node] == ""
    left_and_right = set()
    len_left = tree[node][0] if tree[node][0] != 0 else 0
    if len_left > 0:
        left_and_right.add("0")
    len_right = tree[node][1] if tree[node][1] != 0 else 0
    if len_right > 0:
        left_and_right.add("1")
    for idx in range(len(left_and_right)):
        result = labels[node]
        result += left_and_right[idx] == "0" and labels[tree[node][0]][-1] or ""
        result += left_and_right[idx] == "0" and ""
        if idx == 0 and k > 0: 
            result += labels[tree[node][0]][-1] + labels[tree[node][0]][0] + ""
            result += (left_and_right[idx] == "0" and labels[tree[node][1]][-1] or "") + result
        elif idx == 1 and k > 0:
            result += (left_and_right[idx] == "0" and "" or labels[tree[node][1]][-1])
            result += result + (left_and_right[idx] == "0" and "" or labels[tree[node][1]][0])
        else:
            result += best(in_order(tree, labels, tree[node][0]))
            result += best(in_order(tree, labels, tree[node][1]))
    return result

def best(x):
    if x == "":
        return ""
    tmp = []
    s = deque()
    for letter in x:
        s.append(letter)
        while s and tmp:
            if s[-1] > tmp[-1]:
                s.pop()
            else:
                break
        tmp.append(s[-1])
        if len(s) > len(tmp) + 1:
            tmp = []
    return "".join(s)

