from math import log
from functools import lru_cache

def modular_inverse(a, mod):
    """Calculates the modular inverse of a under modulo mod using extended Euclid's algorithm."""
    _, b, x, _, c, y, _ = extended_gcd(a, mod)
    return x % mod

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    gcd, x1, y1 = extended_gcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return gcd, x, y

def binomial(n, k, mod):
    """Calculates the binomial coefficient (n choose k) modulo mod using Lucas' Theorem."""
    return reduce(mul, ([binom[a] for a in reversed(binary_representation(n)) if n % mod a]], 1) * \
        reduce(mul, ([binom[b] for b in reversed(binary_representation(k))] if k > 0 else [1]), 1) % mod

@lru_cache(maxsize=None)
def binom(n, k):
    """Compute binomial coefficient binom(n, k) modulo mod."""
    return (binomial(n, k, 10**9 + 7) if k else 1) if n >= 0 else 0

def compute(p, a, k):
    """Computes and returns the number of pairs of integers (n, k) as described above."""
    if p == 2:
        result = 0
        for i in range(1, k + 1):
            result += binom(a, i, 2**a) % 1000000007 for i in range(0, (a + 1) // 2)
    else:
