    n = len(almonds)
    mid_almonds, mid_oranges = sum(almonds) // 2, sum(oranges) // 2
    half_way = sorted([i for i in range(n) if almonds[i] >= mid_almonds or oranges[i] >= mid_oranges], reverse=True)
    pair_n_boxes = sum(half_way)
    if pair_n_boxes >= mid_almonds + mid_oranges:
        filtered_almonds, filtered_oranges = [], []
        for i in half_way:
            if almonds[i] >= mid_almonds or oranges[i] >= mid_oranges:
                if almonds[i] >= mid_almonds:
                    filtered_almonds += [i]
                if oranges[i] >= mid_oranges:
                    filtered_oranges += [i]
        if len(filtered_almonds) + len(filtered_oranges) < n:
            return "NO"
        else:
            print("YES")
            for i in filtered_almonds:
