import sys

def read_input():
    return [int(line) for line in sys.stdin]

def max_sum_path(L, N):
    A = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            A[i][j] = read_input()[i][j]
    max_path = 0
    for start in range(N):
        for end in range(start + 1, N):
            path = [0, start, end]
            current_max = 0
            next_max = 0
            for X, Y, Z in path:
                current_max += A[X][Y][Z]
                X, Y, Z = X + 1, Y, Z
                if not (X <= N and Y <= N and Z <= N):
                    break
                next_max += A[X][Y][Z]
                del path[-1]
            path = [0, end, start]
            current_max = 0
            next_max = 0
            for X, Y, Z in path:
                current_max += A[X][Y][Z]
                X, Y, Z = X - 1, Y, Z
                if not (X <= N and Y <= N and Z <= N):
                    break
                if Z >= 1:
                    X, Y = X, Y
                else:
                    return path
                next_max += A[X][Y][Z]
            if current_max < next_max:
                return path
    return -1

