def lexicographically_smallest_string_representation(n, k, c):
    # Convert the string representation to a tree
    tree = {}
    for i in range(1, n + 1):
        tree[i] = {'label': c[i - 1], 'left': 0, 'right': 0}

    def update_bounds(node, parent):
        left_bounds = []
        right_bounds = []
        left_label = ""
        right_label = ""
        for child in (tree[node]['left'], tree[node]['right']):
            if tree[child]:
                left_bounds.append(tree[child]['bounds'][0])
                right_bounds.append(tree[child]['bounds'][1])
                left_label += tree[child]['label']
                right_label += tree[child]['label']
        tree[node]['bounds'] = min(left_bounds), max(right_bounds)
        if left_label and right_label:
            tree[node]['label'] = left_label + right_label

    def merge_labels(node, parent, lower_bound, upper_bound, k):
        if node == 1:
            ord_val = ord(tree[node]['label'][0]) - ord('a')
            # Only need to check for duplicates if there are duplicates of the current letter
            if ord_val < k or ord_val != k and lower_bound <= k - ord_val:
                return max_lower_bound(ord_val + 1, ord_val), lower_bound
            else:
                return max_lower_bound(k, k - 1), lower_bound
        elif parent:
            lower_bound = max_lower_bound(lower_bound, ord_val)
            if lower_bound > ord(k - 1) and lower_bound <= ord(k - k):
                return lower_bound, k

    def max_lower_bound(lower_bound, upper_bound, lexicographically_smallest):
        k = ord(lexicographically_smallest) - ord('a')
        if lower_bound == upper_bound:
            lower_bound = update_bounds(node, parent)[0]
            if lower_bound <= k:
                return lower_bound, k
            else:
                return lower_bound, k
        else:
            diff_pos = lower_bound % 26
            diff_sign = 1 if lower_bound < upper_bound else -1
            diff = diff_pos - diff_sign
            next_lower_bound = max(
                [
                    k + diff if k + diff == 2 * 26 or k + diff > 26
                    else k + diff - (diff_sign if diff < 0 else 0)
                    for k in range(ord('a') - 1, k - 1, -1)
                    if k + diff == 0 or k + diff > 26
                    else
                    [k + diff - (diff_sign if diff < 0 else 0)]
                ]
            )
            if next_lower_bound == 0 or next_lower_bound == k + 1 and lower_bound == upper_bound:
                next_lower_bound = lower_bound
            # Recursively call update_bounds to deal with possible duplicates of tree
            return max(
                merge_labels(
                    tree[node]['left'],
                    parent,
                    next_lower_bound,
                    ord('a') - 1,
                    1,
                ),
                max(
                    merge_labels(
                        tree[node]['right'],
                        parent,
                        next_lower_bound,
                        1,
                        1,
                    ),
                    diff_pos + (diff_sign if diff < 0 else 0)
                ),
            )

    def in_order(node, traversal):
        if tree[node]['left'] != 0:
            in_order(tree[node]['left'], traversal)
        traversal.append(tree[node]['label'])
        if tree[node]['right'] != 0:
            in_order(tree[node]['right'], traversal)

    # Only need to call the private function if we actually have a tree to explore
    if tree[1]['left'] != 0 or tree[2]['left'] != 0:
        in_order(1, [])

    def print_traversal(traversal):
        print(''.join(traversal))

    return print_traversal(['\n'.join(list(map(''.join, zip(*reversed(tree[node]['label']) if tree[node]['label'] else list(map(''.join, zip((node,) + ()), range(1, node))))) for node in reversed(range(1, n + 1))))]
