def game_winner(initial_contour, terminal_contours, n, m):
    score = [-1] * n
    memo = {}

    def dfs(i, lo, hi, cost):
        key = tuple((lo, hi, cost))
        if key in memo:
            return memo[key]
        if cost > 0:
            lo2 = lo + 1
            hi2 = max(hi - 1, n)
        else:
            lo2 = max(lo, lo - 1)
            lo2 = min(lo + n + 1, hi2)
            hi2 = hi
        if i >= n or [lo2, hi2] in terminal_contours:
            memo[key] = 0
        else:
