def find_subsets(nums):
    lengths = sorted(nums, reverse=True)
    subsets = []
    for i in range(len(lengths)):
        if i % 2 == 0:
            for subset in subsets:
                subset[i] = 1
                subs = []
                for j in range(i):
                    subs.append(''.join(map(str, subset)))
                subsets += subs
        else:
            for subset in sorted(subsets, key=lambda x: ''.join(map(str, subset))):
                subset[i] = 1
                subs = []
                for j in range(i):
                    subs.append(''.join(map(str, subset)))
                subsets += subs
    return subsets

n = int(input())
nums = list(map(int, input().split()))
ops = len(nums)
print(ops)
subsets = find_subsets(nums)
for subset in subsets:
    print(''.join(map(str, subset)))
```

