import sys

def buy_bags(n, m):
    if n > m:
        return "NO"
    else:
        return "YES", n, sorted(range(1, m+1), key=lambda x: x>n//2)

n, m = map(int, input().split())
result = buy_bags(n, m)
print(result[0])
if result[1] == "YES": 
    print(result[2])
